// Repro driver for pingdotgg/t3code#27409: real installer, real filesystem, real child process.
// The "release asset" is a script whose first launch per file takes FIRST_LAUNCH_SECONDS,
// emulating an on-access antivirus scan of a never-launched executable.
// Usage: node drive.ts <worktree> <firstLaunchSeconds> [attempts]
import { createHash } from "node:crypto";
import { pathToFileURL } from "node:url";
import * as NodeServices from "@effect/platform-node/NodeServices";
import * as ConfigProvider from "effect/ConfigProvider";
import * as Effect from "effect/Effect";
import * as FileSystem from "effect/FileSystem";
import * as Layer from "effect/Layer";
import { HttpClient, HttpClientResponse } from "effect/http";

const [worktree, firstLaunchSeconds, attemptsArg] = process.argv.slice(2);
const RelayClient = await import(pathToFileURL(`${worktree}/packages/shared/src/relayClient.ts`).href);
const HostProcess = await import(pathToFileURL(`${worktree}/packages/shared/src/HostProcess.ts`).href);
const attempts = Number(attemptsArg ?? 1);

const script = `#!/bin/sh
if [ ! -e "$0.scanned" ]; then sleep ${firstLaunchSeconds}; : > "$0.scanned"; fi
echo "cloudflared version ${RelayClient.CLOUDFLARED_VERSION} (built 2026-10-26T02:34 UTC)"
`;
const bytes = new TextEncoder().encode(script);
const releaseAsset = {
  url: "https://example.test/cloudflared",
  sha256: createHash("sha256").update(bytes).digest("hex"),
  archive: "binary",
} as const;

const layer = Layer.mergeAll(
  NodeServices.layer,
  Layer.succeed(
    HttpClient.HttpClient,
    HttpClient.make((request) =>
      Effect.succeed(HttpClientResponse.fromWeb(request, new Response(bytes.buffer as ArrayBuffer))),
    ),
  ),
  Layer.succeed(HostProcess.Platform, "linux"),
  Layer.succeed(HostProcess.Architecture, "x64"),
  Layer.succeed(HostProcess.Environment, { PATH: "" }),
  ConfigProvider.layer(ConfigProvider.fromEnv({ env: { PATH: "" } })),
);

const program = Effect.gen(function* () {
  const fileSystem = yield* FileSystem.FileSystem;
  const baseDir = yield* fileSystem.makeTempDirectoryScoped({ prefix: "t3-27409-" });
  const manager = yield* RelayClient.makeCloudflaredRelayClient({ baseDir, releaseAsset });
  for (let attempt = 1; attempt <= attempts; attempt++) {
    const started = Date.now();
    const result = yield* manager
      .installWithProgress((event: { stage: string }) =>
        Effect.sync(() => console.log(`  [${((Date.now() - started) / 1000).toFixed(1)}s] stage=${event.stage}`)),
      )
      .pipe(Effect.result);
    const elapsed = ((Date.now() - started) / 1000).toFixed(1);
    console.log(
      result._tag === "Success"
        ? `attempt ${attempt}: INSTALLED ${result.success.version} at ${result.success.executablePath.replace(baseDir, "<baseDir>")} after ${elapsed}s`
        : `attempt ${attempt}: FAILED (${result.failure.reason}) "${result.failure.message}" after ${elapsed}s`,
    );
  }
}).pipe(Effect.scoped, Effect.provide(layer));

await Effect.runPromise(program);
```
</details>

No visible surface changes: this is a server-only fix.

